function validate(input) {
  const [arr, fn] = input;
  if (!Array.isArray(arr) || arr.length < 1) return 'arr must be a non-empty array.';
  if (!fn || typeof fn !== 'object' || Array.isArray(fn) || !Array.isArray(fn.path)) return 'fn must be an object such as { "path": ["x"] }.';
  if (Object.keys(fn).some((key) => key !== 'path' && key !== 'times')) return 'fn may only have path and times.';
  if (fn.times !== undefined && (!Number.isInteger(fn.times) || fn.times === 0 || Math.abs(fn.times) > 10)) return 'times must be a nonzero integer from -10 to 10.';
  if (fn.path.length > 5 || !fn.path.every((step) => typeof step === 'string' || Number.isInteger(step) && step >= 0)) return 'path must list at most 5 object keys or array indexes.';
  const keys = new Set();
  for (const element of arr) {
    let value = element;
    for (const step of fn.path) {
      const fits = typeof step === 'number' ? Array.isArray(value) : value !== null && typeof value === 'object' && !Array.isArray(value);
      value = fits && Object.hasOwn(value, step) ? value[step] : undefined;
    }
    if (typeof value !== 'number' || !Number.isFinite(value) || Math.abs(value * (fn.times ?? 1)) > 1e9) return 'fn must lead to a number with |value| <= 10^9 for every element.';
    const key = value * (fn.times ?? 1);
    if (keys.has(key)) return 'fn must give different numbers for different elements.';
    keys.add(key);
  }
  return null;
}

