function adapt(input, solve, kit) {
  const [arr, spec] = input;
  const times = spec.times ?? 1;
  const fn = (value) => {
    let current = value;
    for (const step of spec.path) current = current[step];
    return times * current;
  };
  const sorted = solve(arr, fn);
  if (!Array.isArray(sorted)) throw new Error('sortBy must return an array.');
  kit.trace(`sortBy returns ${sorted.length} element${sorted.length === 1 ? '' : 's'}`);
  return sorted;
}

