function sortBy(arr, fn) {
  const rest = arr.slice();
  const out = [];
  while (rest.length > 0) {
    let best = 0;
    for (let i = 1; i < rest.length; i++) {
      if (fn(rest[i]) < fn(rest[best])) best = i;
    }
    out.push(rest.splice(best, 1)[0]);
  }
  return out;
}

