function generate(rand, size) {
  const small = size === 'small';
  const count = small ? 1 + Math.floor(rand() * 6) : 1500 + Math.floor(rand() * 501);
  const limit = small ? 12 : 1000000;
  const used = new Set(), values = [];
  while (values.length < count) {
    let value = Math.floor(rand() * (2 * limit + 1)) - limit;
    if (small && rand() < 0.2) value += 0.5;
    if (used.has(value)) continue;
    used.add(value);
    values.push(value);
  }
  const names = ['ann', 'bo', 'cy', 'di'];
  const shape = Math.floor(rand() * 4);
  let arr, path;
  if (shape === 0) {
    arr = values;
    path = [];
  } else if (shape === 1) {
    arr = values.map((value) => ({ name: names[Math.floor(rand() * names.length)], score: value }));
    path = ['score'];
  } else if (shape === 2) {
    arr = values.map((value) => ({ a: { b: value }, c: Math.floor(rand() * 10) }));
    path = ['a', 'b'];
  } else {
    const index = Math.floor(rand() * 3);
    arr = values.map((value) => {
      const row = Array.from({ length: index + 1 + Math.floor(rand() * 2) }, () => Math.floor(rand() * 10));
      row[index] = value;
      return row;
    });
    path = [index];
  }
  const roll = rand();
  if (roll < 0.6) return [arr, { path }];
  return [arr, { path, times: roll < 0.85 ? -1 : 2 }];
}
